sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float centerX;
uniform float centerY;
uniform float sizeFlare;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 p=coord/size-float2(centerX,centerY);float n=fract(sin(floor(phase)+floor(p.x*100.0)*57.0)*43758.5);float spark=step(0.995,n)*exp(-dot(p,p)/(sizeFlare*sizeFlare));return half4(clamp(c.rgb+tint.rgb*half(spark*amount)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
